772	// VoteProposals 返回全部投票提案，按编号排序。
773	func (s *Store) VoteProposals() ([]*VoteProposalView, error) {
774		state, err := s.readState()
775		if err != nil {
776			return nil, err
777		}
778		return voteProposalViews(state), nil
779	}
780	
781	func voteProposalViews(state *storedState) []*VoteProposalView {
782		out := make([]*VoteProposalView, 0, len(state.VoteProposals))
783		for _, p := range state.VoteProposals {
784			out = append(out, voteProposalView(p))
785		}
786		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
787		return out
788	}
789	
790	func voteProposalView(p *storedVoteProposal) *VoteProposalView {
791		spec, err := specOf(p)
792		if err != nil {
793			// 调用方持有的状态均经过 validateState；损坏文件根本无法打开。
794			panic("govflow: building view of corrupt proposal: " + err.Error())
795		}
796		members := make([]MemberView, 0, len(p.Members))
797		for _, m := range p.Members { // 保持成员提交顺序
798			mv := MemberView{
799				ID:       m.ID,
800				Weight:   m.Weight,
801				Path:     append([]string(nil), spec.pathOf[m.ID]...),
802				Delegate: spec.headOf[m.ID],
803			}
804			if to, ok := spec.delegate[m.ID]; ok {
805				mv.Direct = to
806			}
807			members = append(members, mv)
808		}
809		ballots := make([]BallotView, 0, len(p.Ballots))
810		for _, b := range p.Ballots { // 保持首次投票先后顺序
811			ballots = append(ballots, BallotView{
812				Representative: b.Representative,
813				Weight:         b.Weight,
814				Support:        b.Support,
815				VotedAt:        b.VotedAt,
816			})
817		}
818		v := &VoteProposalView{
819			ID:          p.ID,
820			Source:      "vote",
821			State:       p.State,
822			Quorum:      p.Quorum,
823			StartAt:     p.StartAt,
824			Deadline:    p.Deadline,
825			TimelockEnd: p.TimelockEnd,
826			Actions:     copyActions(p.Actions),
827			TotalWeight: spec.total,
828			Members:     members,
829			Ballots:     ballots,
830		}
831		if p.Tally != nil {
832			v.Tally = storedTallyResult(p)
833		}
834		return v
835	}
836	
837	// specOf 从已存储提案重建校验派生物（委托路径、代表归集权重）。
838	func specOf(p *storedVoteProposal) (*proposalSpec, error) {
839		in := &CreateVoteInput{
840			ID:          p.ID,
841			Quorum:      p.Quorum,
842			StartAt:     p.StartAt,
843			Deadline:    p.Deadline,
844			TimelockEnd: p.TimelockEnd,
845			Actions:     p.Actions,
846		}
847		in.Members = make([]VoteMember, len(p.Members))
848		for i, m := range p.Members {
849			in.Members[i] = VoteMember{ID: m.ID, Weight: m.Weight}
850		}
851		in.Delegations = make([]Delegation, len(p.Delegations))
852		for i, d := range p.Delegations {
853			in.Delegations[i] = Delegation{From: d.From, To: d.To}
854		}
855		return validateProposalInput(in)
856	}
857	
858	// validateVoteProposals 在打开状态文件时严格校验全部投票提案：
859	// 编号与 register 来源不冲突；状态机与计票结论一致；票重/代表与名单及委托明细一致；
860	// 首次投票时间落在窗口内；首次计票不早于截止且结论可由明细重放。
861	func validateVoteProposals(state *storedState) error {
862		for key, p := range state.VoteProposals {
863			if p == nil {
864				return fmt.Errorf("voting proposal %q is empty", key)
865			}
866			if p.ID != key || p.ID == "" {
867				return fmt.Errorf("voting proposal key %q does not match id %q", key, p.ID)
868			}
869			if _, collide := state.Proposals[p.ID]; collide {
870				return fmt.Errorf("proposal id %q exists in both proposal sources", p.ID)
871			}
872			switch p.State {
873			case "voting", "passed", "rejected", "executed":
874			default:
875				return fmt.Errorf("voting proposal %q has unknown state %q", p.ID, p.State)
876			}
877			spec, err := specOf(p)
878			if err != nil {
879				return err
880			}
881	
882			// 每张已保存票据都必须明确写出 representative/weight/support/voted_at
883			// 且非 null、JSON 类型正确。先于代表资格与票重核对执行：字段缺损时直接判
884			// 整份文件损坏，绝不能把缺失的 support 默认成反对票、把缺失的 voted_at
885			// 默认成 0 后再继续给出查询或计票的部分结果。
886			for i := range p.Ballots {
887				if err := validateStoredBallot(p.ID, i, &p.Ballots[i]); err != nil {
888					return err
889				}
890			}
891	
892			// 票据明细的代表资格、重复票据、票重与两侧汇总，全部复用首次计票的
893			// verifyBallots：打开重放与首次计票对“票重/代表是否可信”只有一份判定，
894			// 汇总只含最终代表实际投出的票，未投成员权重不进入参与量。
895			counts, err := verifyBallots(p.ID, p.Ballots, spec)
896			if err != nil {
897				return err
898			}
899			// 首次投票时间必须落在窗口 [start, deadline) 内；此约束与票重汇总无关，
900			// 仍只属于打开时的明细校验。
901			for _, b := range p.Ballots {
902				if b.VotedAt < p.StartAt || b.VotedAt >= p.Deadline {
903					return fmt.Errorf("voting proposal %q ballot by %q cast at %d outside window [%d,%d)",
904						p.ID, b.Representative, b.VotedAt, p.StartAt, p.Deadline)
905				}
906			}
907	
908			switch {
909			case p.Tally == nil:
910				if p.State != "voting" {
911					return fmt.Errorf("voting proposal %q is %s but has no tally", p.ID, p.State)
912				}
913			default:
914				if p.State == "voting" {
915					return fmt.Errorf("voting proposal %q has a tally but is still in voting state", p.ID)
916				}
917				// 只要提案有计票结果，for_weight 与 against_weight 就必须各自明确
918				// 写出且为 int64 整数。先于权重重放核对执行：字段缺损时直接判整份
919				// 文件损坏，绝不能把缺失的一侧默认补成 0（恰好等于该侧真实零票重）
920				// 后再继续给出查询或再次计票的结果。明确写出的 0 是合法权重。
921				if err := validateStoredTally(p.ID, p.Tally); err != nil {
922					return err
923				}
924				if p.Tally.TalliedAt < p.Deadline {
925					return fmt.Errorf("voting proposal %q tallied at %d before deadline %d", p.ID, p.Tally.TalliedAt, p.Deadline)
926				}
927				if p.Tally.ForWeight != counts.forWeight || p.Tally.AgainstWeight != counts.againstWeight {
928					return fmt.Errorf("voting proposal %q tally weights for=%d/against=%d do not replay ballots for=%d/against=%d",
929						p.ID, p.Tally.ForWeight, p.Tally.AgainstWeight, counts.forWeight, counts.againstWeight)
930				}
931				// 通过条件同样只有一份：保存状态必须与票据重放出的结论一致，
932				// executed 是 passed 提案执行后的后继状态，仍对应“首次通过”。
933				passedNow := votePasses(counts.forWeight, counts.againstWeight, p.Quorum)
934				if passedNow != (p.State == "passed" || p.State == "executed") {
935					return fmt.Errorf("voting proposal %q state %s does not match quorum/majority replay", p.ID, p.State)
936				}
937			}
938		}
939		return nil
940	}
