183	func runRegister(args []string) {
184		cf := newCmdFlags("register")
185		id := cf.fs.String("id", "", "proposal id (non-empty)")
186		timelockRaw := cf.fs.String("timelock", "", "timelock end timestamp (int64)")
187		var actions actionList
188		cf.fs.Var(&actions, "action", "action text transfer:<account>:<amount> (repeatable, order preserved)")
189		cf.parse(args)
190		if *id == "" {
191			fmt.Fprintf(os.Stderr, "usage error: --id is required\n")
192			os.Exit(2)
193		}
194		timelock := parseIntFlag(cf.fs, "timelock", *timelockRaw)
195	
196		store, err := govflow.Open(cf.state)
197		if err != nil {
198			fail(err)
199		}
200		defer store.Close()
201		existed, err := store.Register(*id, timelock, []string(actions))
202		if err != nil {
203			fail(err)
204		}
205		if cf.asJSON {
