209		}
210		if existed {
211			fmt.Printf("proposal %s already registered with identical content\n", *id)
212		} else {
213			fmt.Printf("registered passed proposal %s (%d action(s), timelock_end=%d)\n", *id, len(actions), timelock)
214		}
215	}
216	
217	// memberList 收集重复的 --member ID:WEIGHT 参数，保持提交顺序。
218	type memberList []govflow.VoteMember
219	
220	func (m *memberList) String() string { return fmt.Sprint([]govflow.VoteMember(*m)) }
221	func (m *memberList) Set(v string) error {
222		id, weight, err := splitMember(v)
223		if err != nil {
224			return err
225		}
226		*m = append(*m, govflow.VoteMember{ID: id, Weight: weight})
227		return nil
