420	func runBalances(args []string) {
421		cf := newCmdFlags("balances")
422		account := cf.fs.String("account", "", "show only this recipient account balance (unknown accounts are 0)")
423		cf.parse(args)
424		store, err := govflow.Open(cf.state)
425		if err != nil {
426			fail(err)
427		}
428		defer store.Close()
429		// 一次快照读取保证资金库与账户余额来自同一份已提交状态，
430		// 不会把并发执行前后的数字拼在一起。
431		snapshot, err := store.BalanceSnapshot()
432		if err != nil {
433			fail(err)
434		}
435		if *account != "" {
436			// 未出现过的账户余额为 0，且不向状态文件新增账户记录。
437			balance := snapshot.Balances[*account]
438			if cf.asJSON {
439				emitJSON(map[string]any{"treasury": snapshot.Treasury, "account": *account, "balance": balance})
440			} else {
441				fmt.Printf("treasury %d\n%s %d\n", snapshot.Treasury, *account, balance)
442			}
443			return
444		}
445		if cf.asJSON {
446			emitJSON(map[string]any{"treasury": snapshot.Treasury, "balances": snapshot.Balances})
447			return
448		}
449		fmt.Printf("treasury %d\n", snapshot.Treasury)
450		accounts := make([]string, 0, len(snapshot.Balances))
451		for acct := range snapshot.Balances {
452			accounts = append(accounts, acct)
453		}
454		sort.Strings(accounts)
455		for _, acct := range accounts {
456			fmt.Printf("%s %d\n", acct, snapshot.Balances[acct])
457		}
458	}
459	
460	func runProposal(args []string) {
461		cf := newCmdFlags("proposal")
462		id := cf.fs.String("id", "", "proposal id")
463		cf.parse(args)
464		if *id == "" {
465			fmt.Fprintf(os.Stderr, "usage error: --id is required\n")
466			os.Exit(2)
467		}
468		store, err := govflow.Open(cf.state)
469		if err != nil {
470			fail(err)
471		}
472		defer store.Close()
473		record, ok, err := store.Proposal(*id)
474		if err != nil {
475			fail(err)
476		}
477		if ok {
478			// 保持既有 JSON 形状：直接输出登记提案记录。
479			if cf.asJSON {
480				emitJSON(record)
481				return
482			}
483			printProposalText(record)
484			return
485		}
486		voteView, vok, verr := store.VoteProposal(*id)
487		if verr != nil {
488			fail(verr)
489		}
490		if !vok {
491			fail(fmt.Errorf("%w: %s", govflow.ErrProposalNotFound, *id))
492		}
493		if cf.asJSON {
494			emitJSON(voteView)
495			return
496		}
497		printVoteProposalText(voteView)
498	}
499	
500	func runProposals(args []string) {
501		cf := newCmdFlags("proposals")
502		cf.parse(args)
503		store, err := govflow.Open(cf.state)
504		if err != nil {
505			fail(err)
506		}
507		defer store.Close()
508		// 一次快照读取保证登记提案与投票提案来自同一份已提交状态，
509		// 不会把并发执行前后的提案状态拼在一起。
510		snapshot, err := store.ProposalsSnapshot()
511		if err != nil {
512			fail(err)
513		}
514		registered := snapshot.Registered
515		voting := snapshot.Voting
516		if cf.asJSON {
517			// 保持既有 JSON 形状：一个数组；登记记录字段不变，投票提案带额外字段。
518			merged := make([]any, 0, len(registered)+len(voting))
519			for _, r := range registered {
520				merged = append(merged, r)
521			}
522			for _, v := range voting {
523				merged = append(merged, v)
524			}
525			emitJSON(merged)
526			return
527		}
528		for _, record := range registered {
529			printProposalText(record)
530		}
531		for _, view := range voting {
532			printVoteProposalText(view)
533		}
534	}
