func (d *delegationList) Set(v string) error {
	from, to, ok := strings.Cut(v, ":")
	if !ok || from == "" || to == "" {
		return fmt.Errorf("malformed delegation %q, expected FROM:TO", v)
	}
	*d = append(*d, govflow.Delegation{From: from, To: to})
	return nil
}

